import { puzzleFinishes } from './themes.js';
import * as T from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
const PALETTE=['#b98b61','#7e9985','#ccaa63','#9b879b','#7d9aa4','#bb8172','#a5a56f'];
const SHAPES=['0,0 4,0 2,2','0,0 2,2 0,4','4,4 4,2 2,4','4,0 4,2 3,1','2,2 3,1 4,2 3,3','2,2 3,3 1,3','0,4 1,3 3,3 2,4'];
export class Puzzle3D{
 constructor(){this.renderer=new T.WebGLRenderer({alpha:true,antialias:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.7));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.outputColorSpace=T.SRGBColorSpace;this.scene=new T.Scene();this.camera=new T.PerspectiveCamera(40,1,.1,100);this.controls=new OrbitControls(this.camera,this.renderer.domElement);this.controls.enableDamping=false;this.controls.enablePan=false;this.controls.minPolarAngle=.1;this.controls.maxPolarAngle=1.45;this.controls.minDistance=7;this.controls.maxDistance=22;this.controls.addEventListener('change',()=>this.draw());this.scene.add(new T.HemisphereLight(0xfff8e8,0x9b9c82,2.5));const light=new T.DirectionalLight(0xffefd7,3);light.position.set(-4,9,5);light.castShadow=true;light.shadow.mapSize.set(1024,1024);Object.assign(light.shadow.camera,{left:-8,right:8,top:8,bottom:-8});light.shadow.normalBias=.03;this.scene.add(light);const fill=new T.DirectionalLight(0xe0eced,1.8);fill.position.set(6,4,-4);this.scene.add(fill);this.root=new T.Group();this.scene.add(this.root);this.ray=new T.Raycaster();this.pointer=new T.Vector2();this.observer=new ResizeObserver(()=>this.resize());this.preset('angle');this.bind();}
 finishColor(color){const f=puzzleFinishes[this.room?.finish]||puzzleFinishes.wood;return ['#c5b18c','#bba681'].includes(color)?f.base:['#e5ddc9','#ede7d8','#f0eadc','#dedbc9','#dfd7bd'].includes(color)?f.tile:['#b39361','#c3a06b'].includes(color)?f.rim:color;}
 box(w,h,d,color,x,y,z,tag){const mesh=new T.Mesh(new T.BoxGeometry(w,h,d),new T.MeshStandardMaterial({color:this.finishColor(color),roughness:.6}));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.tag=tag;this.root.add(mesh);return mesh;}
 cylinder(r,h,color,x,y,z,tag){const mesh=new T.Mesh(new T.CylinderGeometry(r,r,h,48),new T.MeshStandardMaterial({color:this.finishColor(color),roughness:.45}));mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.tag=tag;this.root.add(mesh);return mesh;}
 label(text,x,y,z,size=.4,color='#fff6df',tag){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=128;const ctx=canvas.getContext('2d');ctx.fillStyle=color;ctx.font='54px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,128,64);const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;const m=new T.Mesh(new T.PlaneGeometry(size*2,size),new T.MeshBasicMaterial({map:texture,transparent:true,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.set(x,y,z);m.userData.tag=tag;this.root.add(m);}
 attach(host,room){const changed=this.kind!==room.kind;this.kind=room.kind;this.room=room;if(changed){this.baseDistance=room.kind==='tangram'?16:12;this.preset(room.viewAngle);this.zoom(room.viewZoom);}this.observer.disconnect();host.append(this.renderer.domElement);this.observer.observe(host);this.sync();this.resize();}
 clear(){this.root.traverse(o=>{o.geometry?.dispose();if(o.material){o.material.map?.dispose();o.material.dispose();}});this.root.clear();}
 sync(){this.clear();const r=this.room;let width=7,depth=7;if(r.kind==='huarong'){width=4.4;depth=5.4;}if(r.kind==='hanoi'){width=8;depth=3.6;}if(r.kind==='tangram'){width=9;depth=9;}if(r.kind==='sokoban'){width=r.map[0].length+.3;depth=r.map.length+.3;}this.box(width,.18,depth,'#c5b18c',0,-.18,0);
 if(r.kind==='huarong'){r.state.forEach((b,i)=>{const tag={type:'piece',id:i},x=b[1]+b[3]/2-2,z=b[2]+b[4]/2-2.5;this.box(b[3]-.08,.42,b[4]-.08,r.selected===i?'#d0b06c':PALETTE[i%7],x,.14,z,tag);this.label(b[0],x,.36,z,.38,'#fff6df',tag);});this.label('出口 ↓',0,-.07,2.55,.25,'#785c3c');}
 if(r.kind==='sokoban'){const map=r.map,w=map[0].length,h=map.length;map.forEach((row,y)=>[...row].forEach((c,x)=>{const px=x-w/2+.5,pz=y-h/2+.5,v=y*20+x;this.box(.97,c==='#'?.7:.05,.97,c==='#'?'#819071':'#e5ddc9',px,c==='#'?.3:-.05,pz);if(c==='.')this.cylinder(.28,.03,'#a2b581',px,0,pz);if(r.state.boxes.includes(v)){this.box(.72,.65,.72,'#c3a06b',px,.31,pz);this.label('✧',px,.65,pz,.35);}if(r.state.player===v){this.cylinder(.22,.5,'#ac6f57',px,.25,pz);const head=new T.Mesh(new T.SphereGeometry(.23,24,16),new T.MeshStandardMaterial({color:'#dec8a0'}));head.position.set(px,.65,pz);head.castShadow=true;this.root.add(head);}}));}
 if(r.kind==='sudoku'||r.kind==='nonogram'){const sudoku=r.kind==='sudoku',n=sudoku?9:5,unit=sudoku?.66:.9;for(let i=0;i<n*n;i++){const x=(i%n-(n-1)/2)*unit,z=(Math.floor(i/n)-(n-1)/2)*unit,tag={type:'cell',id:i},v=r.state[i];let color=sudoku?(r.conflict(i)?'#d9a28a':r.selected===i?'#c7b77d':r.givens[i]?'#dedbc9':'#f0eadc'):v===1?'#7e967c':'#ede7d8';this.box(unit-.035,v&&!sudoku?.2:.09,unit-.035,color,x,v&&!sudoku?.06:0,z,tag);if(sudoku&&v)this.label(String(v),x,.055,z,.34,r.givens[i]?'#526049':'#9c6242',tag);if(!sudoku&&v===2)this.label('×',x,.06,z,.35,'#9d927a',tag);}if(sudoku){for(const x of [-.99,.99]){this.box(.035,.02,5.94,'#8a896a',x,.055,0);this.box(5.94,.02,.035,'#8a896a',0,.055,x);}}else{const patterns=['0010001110111110010000100','0101011111111110111000100','0010001110111110101011011'],target=patterns[r.level%3],runs=a=>a.join('').split('0').filter(Boolean).map(v=>v.length).join('·')||'0';for(let i=0;i<5;i++){this.label(runs([...target.slice(i*5,i*5+5)]),-2.65,.02,(i-2)*unit,.3,'#636d52');this.label(runs(Array.from({length:5},(_,j)=>target[j*5+i])),(i-2)*unit,.02,-2.65,.3,'#636d52');}}}
 if(r.kind==='hanoi'){r.state.forEach((peg,i)=>{const x=(i-1)*2.6,tag={type:'peg',id:i};this.box(2.4,.05,2.9,r.selected===i?'#d5c595':'#bba681',x,-.06,0,tag);this.cylinder(.075,2.8,'#b39361',x,1.3,0,tag);peg.forEach((s,j)=>this.cylinder(.28+s/r.count*.85,.23,PALETTE[s%7],x,.15+j*.25,0,tag));this.label(['起点','中转','终点'][i],x,-.025,1.2,.28,'#6b5940',tag);});}
 if(r.kind==='tangram'){this.box(4,.02,4,'#dfd7bd',0,-.05,0);SHAPES.forEach((points,i)=>{const p=r.state[i],shape=new T.Shape();points.split(' ').forEach((point,j)=>{const [x,y]=point.split(',').map(Number);if(j===0)shape.moveTo(x-2,2-y);else shape.lineTo(x-2,2-y);});shape.closePath();const mesh=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:.14,bevelEnabled:true,bevelThickness:.025,bevelSize:.02,bevelSegments:1}),new T.MeshStandardMaterial({color:r.selected===i?'#d2b16d':PALETTE[i],roughness:.55}));mesh.rotation.x=-Math.PI/2;mesh.rotation.z=-p.a*Math.PI/180;mesh.scale.x=p.flip?-1:1;mesh.position.set(p.x/50,.01,p.y/50);mesh.userData.tag={type:'tan',id:i};mesh.castShadow=true;mesh.receiveShadow=true;this.root.add(mesh);if(r.hint){const edges=new T.LineSegments(new T.EdgesGeometry(new T.ShapeGeometry(shape)),new T.LineBasicMaterial({color:'#9b8f71'}));edges.rotation.x=-Math.PI/2;edges.position.y=-.025;this.root.add(edges);}});}
 this.draw();}
 preset(name){const d=this.baseDistance||12,theta=name==='front'?0:name==='side'?Math.PI/2:Math.PI/5,phi=name==='top'?.12:name==='front'||name==='side'?1.15:.72;this.camera.position.set(d*Math.sin(phi)*Math.sin(theta),d*Math.cos(phi),d*Math.sin(phi)*Math.cos(theta));this.controls.target.set(0,0,0);this.controls.update();this.draw();}
 zoom(value){this.camera.position.setLength((this.baseDistance||12)/value);this.controls.update();this.draw();}
 resize(){const host=this.renderer.domElement.parentElement;if(!host)return;const w=Math.max(1,host.clientWidth),h=Math.max(1,host.clientHeight);this.renderer.setSize(w,h,false);this.camera.aspect=w/Math.max(h,1);this.camera.updateProjectionMatrix();this.draw();}
 draw(){if(this.renderer&&this.camera)this.renderer.render(this.scene,this.camera);}
 pick(e){const rect=this.renderer.domElement.getBoundingClientRect();this.pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);this.ray.setFromCamera(this.pointer,this.camera);return this.ray.intersectObjects(this.root.children).find(hit=>hit.object.userData.tag);}
 planePoint(e){this.pick(e);return this.ray.ray.intersectPlane(new T.Plane(new T.Vector3(0,1,0),-.15),new T.Vector3());}
 bind(){const canvas=this.renderer.domElement;canvas.addEventListener('pointerdown',e=>{const hit=this.pick(e);this.down={x:e.clientX,y:e.clientY,tag:hit?.object.userData.tag};if(this.room?.kind==='tangram'&&this.down.tag?.type==='tan'){const id=this.down.tag.id,p=this.room.state[id];this.room.selected=id;if(p.locked)return;this.controls.enabled=false;this.drag={id,point:this.planePoint(e),x:p.x,y:p.y};this.room.save();canvas.setPointerCapture(e.pointerId);}},true);canvas.addEventListener('pointermove',e=>{if(!this.drag)return;const point=this.planePoint(e);if(!point||!this.drag.point)return;const p=this.room.state[this.drag.id];p.x=Math.max(-110,Math.min(110,this.drag.x+(point.x-this.drag.point.x)*50));p.y=Math.max(-110,Math.min(110,this.drag.y+(point.z-this.drag.point.z)*50));this.sync();});const finish=e=>{if(this.drag){this.room.snap(this.room.state[this.drag.id]);this.drag=null;this.controls.enabled=true;this.room.render();return;}if(this.down&&Math.hypot(e.clientX-this.down.x,e.clientY-this.down.y)<7){const tag=this.down.tag;if(tag&&tag.type!=='tan')this.room.host.querySelector(`[data-${tag.type}="${tag.id}"]`)?.click();}this.down=null;};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',()=>{this.drag=null;this.controls.enabled=true;});}
}
